/* ================================================================
   WorkWise Visa — Content Data
   All section data as strongly-typed arrays.
   ================================================================ */

// ── Types ────────────────────────────────────────────────────────

export interface Country {
  name: string;
  code: string;
  flag: string;
  region: string;
  description: string;
  visaTypes: string[];
  processingTime: string;
  popularRoles: string[];
}

export interface Service {
  title: string;
  description: string;
  iconName: string;
  features: string[];
}

export interface Testimonial {
  name: string;
  role: string;
  company: string;
  country: string;
  flag: string;
  quote: string;
}

export interface FAQItem {
  question: string;
  answer: string;
}

export interface ProcessStep {
  step: number;
  title: string;
  description: string;
  iconName: string;
  duration: string;
}

export interface Stat {
  value: number;
  suffix: string;
  label: string;
  iconName: string;
}

export interface WhyUsPoint {
  title: string;
  description: string;
  iconName: string;
}

export interface BlogPost {
  id: string;
  title: string;
  slug?: string;
  category: string;
  date: string;
  readTime: string;
  excerpt: string;
  content?: string;
  image: string;
  author: string;
  tags: string[];
  metaTitle?: string;
  metaDescription?: string;
  metaKeywords?: string;
  canonicalUrl?: string;
  published?: boolean;
  featured?: boolean;
  views?: number;
}

export interface Industry {
  id: string;
  title: string;
  seoTagline: string;
  description: string;
  iconName: string;
  demandLevel: "Very High" | "High" | "Urgent Shortage";
  popularRoles: string[];
  topDestinations: string[];
  averageSalary: string;
  keyBenefits: string[];
}

export interface JobDemand {
  id: string;
  title: string;
  company: string;
  country: string;
  flag: string;
  category: string;
  salary: string;
  totalOpenings: number;
  visaType: string;
  interviewDate: string;
  venue: string;
  dutyHours: string;
  perks: string[];
  requirements: string[];
  postedDate: string;
  urgent: boolean;
}

